const grpc = require('@grpc/grpc-js');
const { k8sAppsApi } = require('../lib/kubernetes');
const { verifyToken } = require('../lib/tokens');
const { db } = require('../db');

async function restartContainerInstance(call, callback) {
  const user = await verifyToken(call.metadata.get('token')[0]);
  if (!user) return callback({ code: grpc.status.UNAUTHENTICATED });

  const { deploymentName, namespace } = call.request;

  const tenantCheck = await db.query(
    'SELECT id FROM tenant_namespaces WHERE namespace = $1 AND tenant_id = $2',
    [namespace, user.tenantId]
  );
  if (tenantCheck.rowCount === 0) {
    return callback({ code: grpc.status.PERMISSION_DENIED, message: 'Forbidden: unauthorized namespace' });
  }

  await k8sAppsApi.patchNamespacedDeployment(
    deploymentName,
    namespace,
    { spec: { template: { metadata: { annotations: { 'kubectl.kubernetes.io/restartedAt': new Date().toISOString() } } } } },
    undefined, undefined, undefined, undefined, undefined,
    { headers: { 'Content-Type': 'application/strategic-merge-patch+json' } }
  );

  return callback(null, { restarted: true, deploymentName });
}
